  '四慧心|那那': '兩輪都是「那」——見煩惱。純見之惑最重，煩惱障重故退落三階，回到初信心——聞說因緣假名、無量四諦與中道佛性、常住三寶之理，隨順不疑。‖譜曰：（初信心位下云：那那等三。煩惱障重。須修助道。故借用三藏五停心也。）',
