  '六不退心|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
