  // ═══ 七 · 七護法心 ═══
  '七護法心|那那': '兩輪都是「那」——見煩惱。純見猶未能永伏，故仍退；但此位較前五心稍堅固，只退二階，落五定心——但除其病而不除法，如金鎞去膜護珠。‖譜曰：（六不退心位下云：然猶未證三種不退。但較前五心稍堅固耳。……而那那純見。謨謨純愛。猶未能永伏也。）',
  '七護法心|那謨': '「那」是見煩惱，「謨」是愛煩惱。六不退心中如次修行三十七品，令其調適而能伏煩惱，見愛相雜之擲便無從安立，所以不行，安住本位。‖譜曰：（六不退心位下云：於定心中。如次修行三十七品。令其調適。能伏煩惱。……故那謨相雜。雖可不行。）',
