  '四生貴住|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

  // ═══ 十五 · 五方便具足住 ═══
  '五方便具足住|那那': '兩輪都是「那」——見煩惱。六住已前煩惑未盡，出假化物時遇大違緣，分別心生便退菩提願，故須修無生懺：先用作法取相而導其流，隨即觀罪性空以塞其源。‖譜曰：（初發心住位下云：是故六住已前。煩惑未盡。猶得有退轉義。那那須修無生懺也。）',
  '五方便具足住|那謨': '「那」是見煩惱，「謨」是愛煩惱。初發心住雖已斷分別我見，但六住以前煩惑未盡。此擲在位次表中未另列去處，故不行，安住本位；不能解作見愛二惑已盡。‖譜曰：（初發心住位下云：能斷分別我見。及從分別所起惡煩惱業。……是故六住已前。煩惑未盡。猶得有退轉義。）',
  '五方便具足住|謨謨': '兩輪都是「謨」——愛煩惱。初發心住至六正心住，煩惑尚未斷盡，不能解作純愛之惑已斷。此擲在位次表中未另列去處，故不行，安住本位。‖譜曰：（初發心住位下云：是故六住已前。煩惑未盡。猶得有退轉義。）',
  '五方便具足住|阿阿': '兩輪都是「阿」——布施。施善之力進一階，入六正心住——成就第六般若法門，准位應同阿羅漢向。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|阿彌': '「阿」表布施，「彌」表持戒。施戒二善相資，進二階，入七不退住——入於無生畢竟空界，准位應同阿羅漢果、通教已辦地。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入八童真住——不以邪倒破菩提心，離諸過失，准位應同辟支佛地。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|阿陀': '「阿」表布施，「陀」表禪定。施定相資，功力與彌彌相等，同進三階，入八童真住——不以邪倒破菩提心，離諸過失，准位應同辟支佛地。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入九法王子住——從佛法生解，當紹佛位，應同通教菩薩地。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入十灌頂住——既紹佛種必受佛職，界內塵沙惑盡、俗諦理明，堪作人天師導。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入九法王子住——從佛法生解，當紹佛位，應同通教菩薩地。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入十灌頂住——既紹佛種必受佛職，界內塵沙惑盡、俗諦理明，堪作人天師導。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '五方便具足住|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十住而階五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
  '五方便具足住|彌佛': '「彌」表持戒，「佛」表無漏善慧。別教三十心是圓教所接之位；此擲按其當位被接入圓，故成圓十信位——圓伏無明，發相似解。‖譜曰：（初發心住位下云：彌佛按位可接。故成圓信。）',
  '五方便具足住|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲歸方便淨土，永離退轉之緣，故生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初發心住位下云：陀佛歸方便淨。永離退緣。）',
  '五方便具足住|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤顯妙而勝進被接入圓，故登圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初發心住位下云：佛佛開麤顯妙。亦是勝進接也。）',
  '五方便具足住|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '五方便具足住|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '五方便具足住|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '五方便具足住|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '五方便具足住|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '五方便具足住|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

