  '六正心住|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入十灌頂住——既紹佛種必受佛職，界內塵沙惑盡、俗諦理明，堪作人天師導。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '六正心住|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入初歡喜行——施波羅密增上，能生自他歡喜心。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '六正心住|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入十灌頂住——既紹佛種必受佛職，界內塵沙惑盡、俗諦理明，堪作人天師導。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '六正心住|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入初歡喜行——施波羅密增上，能生自他歡喜心。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '六正心住|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十住而階六善現行——般若波羅密增上，生生常在諸佛會中，於一切法皆明了。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
  '六正心住|彌佛': '「彌」表持戒，「佛」表無漏善慧。別教三十心是圓教所接之位；此擲按其當位被接入圓，故成圓十信位——圓伏無明，發相似解。‖譜曰：（初發心住位下云：彌佛按位可接。故成圓信。）',
