  '六正心住|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤顯妙而勝進被接入圓，故登圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初發心住位下云：佛佛開麤顯妙。亦是勝進接也。）',
