  // ═══ 十七 · 七不退住 ═══
  '七不退住|那那': '兩輪都是「那」——見煩惱。本位已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。',
  '七不退住|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '七不退住|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
