  '十灌頂住|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '十灌頂住|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '十灌頂住|阿阿': '兩輪都是「阿」——布施。施善之力進一階，入初歡喜行——施波羅密增上，能生自他歡喜心。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|阿彌': '「阿」表布施，「彌」表持戒。施戒二善相資，進二階，入二饒益行——戒波羅密增上，滅惡生善，攝化眾生令其得法利。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入三無瞋恨行——忍波羅密增上，不生嫌恚，常有謙恭。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|阿陀': '「阿」表布施，「陀」表禪定。施定相資，功力與彌彌相等，同進三階，入三無瞋恨行——忍波羅密增上，不生嫌恚，常有謙恭。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入四無盡行——精進波羅密增上，功德無盡，無能屈伏令阻撓。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入四無盡行——精進波羅密增上，功德無盡，無能屈伏令阻撓。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '十灌頂住|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十住而階十真實行——智波羅密增上，照一切法非如非異，得悟真實之性。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
  '十灌頂住|彌佛': '「彌」表持戒，「佛」表無漏善慧。別教三十心是圓教所接之位；此擲按其當位被接入圓，故成圓十信位——圓伏無明，發相似解。‖譜曰：（初發心住位下云：彌佛按位可接。故成圓信。）',
  '十灌頂住|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲歸方便淨土，永離退轉之緣，故生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初發心住位下云：陀佛歸方便淨。永離退緣。）',
  '十灌頂住|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤顯妙而勝進被接入圓，故登圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初發心住位下云：佛佛開麤顯妙。亦是勝進接也。）',
  '十灌頂住|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '十灌頂住|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '十灌頂住|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '十灌頂住|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '十灌頂住|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '十灌頂住|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

