  // ═══ 二十一 · 初歡喜行 ═══
  '初歡喜行|那那': '兩輪都是「那」——見煩惱。七不退住已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
