  '初歡喜行|阿彌': '「阿」表布施，「彌」表持戒。施戒二善相資，進二階，入三無瞋恨行——忍波羅密增上，不生嫌恚，常有謙恭。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入四無盡行——精進波羅密增上，功德無盡，無能屈伏令阻撓。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|阿陀': '「阿」表布施，「陀」表禪定。施定相資，功力與彌彌相等，同進三階，入四無盡行——精進波羅密增上，功德無盡，無能屈伏令阻撓。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入六善現行——般若波羅密增上，生生常在諸佛會中，於一切法皆明了。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入六善現行——般若波羅密增上，生生常在諸佛會中，於一切法皆明了。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '初歡喜行|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十行而階初救護眾生離眾生相迴向——不住空故救護眾生，不住有故離眾生相，雙遣二邊而正觀中道。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
  '初歡喜行|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲不離佛故，即生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：彌佛即生方便淨者。不離佛故。',
  '初歡喜行|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲勝進被接入圓，故當圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：陀佛圓住者。勝進接故。',
  '初歡喜行|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤成妙而轉入圓教，故當圓十行位——十住之後更斷十品無明。‖譜曰：佛佛圓行者。開麤成妙故。下皆准知。',
  '初歡喜行|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '初歡喜行|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '初歡喜行|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '初歡喜行|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '初歡喜行|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '初歡喜行|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

