  '二饒益行|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '二饒益行|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

  // ═══ 二十三 · 三無瞋恨行 ═══
  '三無瞋恨行|那那': '兩輪都是「那」——見煩惱。七不退住已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '三無瞋恨行|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '三無瞋恨行|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '三無瞋恨行|阿阿': '兩輪都是「阿」——布施。施善之力進一階，入四無盡行——精進波羅密增上，功德無盡，無能屈伏令阻撓。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|阿彌': '「阿」表布施，「彌」表持戒。施戒二善相資，進二階，入五離癡亂行——禪波羅密增上，有慧故無癡，有定故無亂。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入六善現行——般若波羅密增上，生生常在諸佛會中，於一切法皆明了。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|阿陀': '「阿」表布施，「陀」表禪定。施定相資，功力與彌彌相等，同進三階，入六善現行——般若波羅密增上，生生常在諸佛會中，於一切法皆明了。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入七無著行——方便波羅密增上，於生死涅槃二邊皆不著。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入八尊重行——願波羅密增上，所有善根最為尊重，極難得。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入七無著行——方便波羅密增上，於生死涅槃二邊皆不著。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入八尊重行——願波羅密增上，所有善根最為尊重，極難得。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三無瞋恨行|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十行而階三等一切佛迴向——三世佛法，一切時行。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
  '三無瞋恨行|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲不離佛故，即生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初歡喜行位下云：彌佛即生方便淨者。不離佛故。）',
  '三無瞋恨行|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲勝進被接入圓，故當圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初歡喜行位下云：陀佛圓住者。勝進接故。）',
  '三無瞋恨行|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤成妙而轉入圓教，故當圓十行位——十住之後更斷十品無明。‖譜曰：（初歡喜行位下云：佛佛圓行者。開麤成妙故。下皆准知。）',
  '三無瞋恨行|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三無瞋恨行|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三無瞋恨行|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三無瞋恨行|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三無瞋恨行|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三無瞋恨行|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

