  '四無盡行|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲亦得漸超，故越出十行而階四至一切處迴向——以大願力普入一切國土，供養一切諸佛。‖譜曰：（初發心住位下云：阿佛亦得漸超。故階初行。）',
