  '三等一切佛迴向|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入六隨順平等善根迴向——行一切善，普皆迴向眾生同成佛道，更無二趣。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|阿陀': '「阿」表布施，「陀」表禪定。施定相資，功力與彌彌相等，同進三階，入六隨順平等善根迴向——行一切善，普皆迴向眾生同成佛道，更無二趣。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入七隨順等觀一切眾生迴向——觀諸眾生所有善惡一相無二，皆順實相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入八真如相迴向——心得自在，等三世佛，常照有無而不得二相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，進四階，入七隨順等觀一切眾生迴向——觀諸眾生所有善惡一相無二，皆順實相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍能增進品位，進五階，入八真如相迴向——心得自在，等三世佛，常照有無而不得二相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '三等一切佛迴向|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲得相似中觀，亦是按其當位被接入圓，故當圓十信位——圓伏無明，發相似解。‖譜曰：（初救護眾生離眾生相迴向位下云：阿佛圓信者。得相似中觀故。亦是按位接故。）',
  '三等一切佛迴向|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲恆淨佛國土，亦仍不離佛故，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初救護眾生離眾生相迴向位下云：彌佛方便者。恆淨佛國土故。亦仍不離佛故。）',
  '三等一切佛迴向|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲仍是勝進被接入圓，故當圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初救護眾生離眾生相迴向位下云：陀佛圓住者。仍是勝進接故。）',
  '三等一切佛迴向|佛佛': '兩輪都是「佛」，在此位表圓頓門。亦是開麤成妙而轉入圓教，故當圓十迴向位——十行之後更破十品無明。‖譜曰：（初救護眾生離眾生相迴向位下云：佛佛圓向者。亦開麤成妙故。下皆准知。）',
  '三等一切佛迴向|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三等一切佛迴向|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三等一切佛迴向|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三等一切佛迴向|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三等一切佛迴向|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '三等一切佛迴向|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

  // ═══ 三十四 · 四至一切處迴向 ═══
  '四至一切處迴向|那那': '兩輪都是「那」——見煩惱。七不退住已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '四至一切處迴向|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '四至一切處迴向|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '四至一切處迴向|阿阿': '兩輪都是「阿」——布施。施善之力進一階，入五無盡功德藏迴向——以常住之法授與前人。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '四至一切處迴向|阿彌': '「阿」表布施，「彌」表持戒。施戒二善相資，進二階，入六隨順平等善根迴向——行一切善，普皆迴向眾生同成佛道，更無二趣。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '四至一切處迴向|彌彌': '兩輪都是「彌」——持戒。戒力既厚，進三階，入七隨順等觀一切眾生迴向——觀諸眾生所有善惡一相無二，皆順實相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
