  '四至一切處迴向|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，進四階，入八真如相迴向——心得自在，等三世佛，常照有無而不得二相。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
  '四至一切處迴向|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，進五階，入九無縛解脫迴向——照了三世諸法非有非空，本無縛著。‖譜曰：（初發心住位下云：阿阿等八。按位漸進。如常可知。）',
