  '七隨順等觀一切眾生迴向|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲恆淨佛國土，亦仍不離佛故，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初救護眾生離眾生相迴向位下云：彌佛方便者。恆淨佛國土故。亦仍不離佛故。）',
