  '九無縛解脫迴向|阿陀': '「阿」表布施，「陀」表禪定。施定相資，力雖增而於教道中未得出世正慧，更無可勝進，故止於十法界無量迴向——覺一切法中道無相。‖譜曰：（六隨順平等善根迴向位下云：陀陀。謨佛。亦皆十向者。於教道中。未得出世正慧。更無可勝進故。下諸位中。准此應知。）',
  '九無縛解脫迴向|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，力雖增而於教道中未得出世正慧，更無可勝進，故止於十法界無量迴向——覺一切法中道無相。‖譜曰：（六隨順平等善根迴向位下云：陀陀。謨佛。亦皆十向者。於教道中。未得出世正慧。更無可勝進故。下諸位中。准此應知。）',
  '九無縛解脫迴向|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，力雖增而於教道中未得出世正慧，更無可勝進，故止於十法界無量迴向——覺一切法中道無相。‖譜曰：（六隨順平等善根迴向位下云：陀陀。謨佛。亦皆十向者。於教道中。未得出世正慧。更無可勝進故。下諸位中。准此應知。）',
  '九無縛解脫迴向|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍能增進品位，力雖增而於教道中未得出世正慧，更無可勝進，故止於十法界無量迴向——覺一切法中道無相。‖譜曰：（六隨順平等善根迴向位下云：陀陀。謨佛。亦皆十向者。於教道中。未得出世正慧。更無可勝進故。下諸位中。准此應知。）',
  '九無縛解脫迴向|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。於教道之中而入證道，雖已有佛慧，仍是帶權而說，故登初歡喜地——初破無明，證真中道，捨異生性入同生性，故大樂歡喜。‖譜曰：謨佛初地者。於教道中。而入證道。雖有佛慧。仍帶權故。次位那佛。准此應知。',
  '九無縛解脫迴向|阿佛': '「阿」表布施，「佛」表無漏善慧。此擲得相似中觀，亦是按其當位被接入圓，故當圓十信位——圓伏無明，發相似解。‖譜曰：（初救護眾生離眾生相迴向位下云：阿佛圓信者。得相似中觀故。亦是按位接故。）',
  '九無縛解脫迴向|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲恆淨佛國土，亦仍不離佛故，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：（初救護眾生離眾生相迴向位下云：彌佛方便者。恆淨佛國土故。亦仍不離佛故。）',
  '九無縛解脫迴向|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲仍是勝進被接入圓，故當圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初救護眾生離眾生相迴向位下云：陀佛圓住者。仍是勝進接故。）',
  '九無縛解脫迴向|佛佛': '兩輪都是「佛」，在此位表圓頓門。亦是開麤成妙而轉入圓教，故當圓十迴向位——十行之後更破十品無明。‖譜曰：（初救護眾生離眾生相迴向位下云：佛佛圓向者。亦開麤成妙故。下皆准知。）',
  '九無縛解脫迴向|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '九無縛解脫迴向|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '九無縛解脫迴向|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '九無縛解脫迴向|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '九無縛解脫迴向|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
