  // ═══ 四十 · 十法界無量迴向 ═══
  '十法界無量迴向|那那': '兩輪都是「那」——見煩惱。七不退住已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '十法界無量迴向|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '十法界無量迴向|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '十法界無量迴向|阿阿': '兩輪都是「阿」——布施。十向已滿而緣修已極，功不唐捐；只是尚未發中道佛慧，故必歸有餘之國，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：阿阿等六。皆方便淨土者。緣修已極。功不唐捐。既未發中道佛慧。必歸有餘國故。',
  '十法界無量迴向|阿彌': '「阿」表布施，「彌」表持戒。十向已滿而緣修已極，功不唐捐；只是尚未發中道佛慧，故必歸有餘之國，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：阿阿等六。皆方便淨土者。緣修已極。功不唐捐。既未發中道佛慧。必歸有餘國故。',
  '十法界無量迴向|彌彌': '兩輪都是「彌」——持戒。十向已滿而緣修已極，功不唐捐；只是尚未發中道佛慧，故必歸有餘之國，生方便有餘淨土——修方便道的三乘所居，出三界外受法性身，非分段生。‖譜曰：阿阿等六。皆方便淨土者。緣修已極。功不唐捐。既未發中道佛慧。必歸有餘國故。',
