  '七遠行地|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '七遠行地|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

  // ═══ 四十八 · 八不動地 ═══
  '八不動地|那那': '兩輪都是「那」——見煩惱。七不退住已入於無生畢竟空界，准位同阿羅漢果、通教已辦地，三界之惑既盡，此擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '八不動地|那謨': '「那」是見煩惱，「謨」是愛煩惱。自七不退住起，三界見思惑已斷盡，見愛相雜之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '八不動地|謨謨': '兩輪都是「謨」——愛煩惱。自七不退住起，三界見思惑已斷盡，純愛之擲無從安立，所以不行，安住本位。‖譜曰：（七不退住位下云：入於無生畢竟空界。名不退住。准位應同阿羅漢果。已辦地也。）',
  '八不動地|阿阿': '兩輪都是「阿」——布施。今約教門而論，登地以後這一路散善已不能更增品位，所以不行，安住本位。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|阿彌': '「阿」表布施，「彌」表持戒。今約教門而論，登地以後這一路散善已不能更增品位，所以不行，安住本位。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|彌彌': '兩輪都是「彌」——持戒。今約教門而論，登地以後這一路散善已不能更增品位，所以不行，安住本位。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|阿陀': '「阿」表布施，「陀」表禪定。依教道而論，八地的真無生法忍最難階入，此擲之力不足以越之，所以不行，安住本位。‖譜曰：（七遠行地位下云：阿陀不行者。依教道中。八地真無生法忍最難階故。）',
  '八不動地|彌陀': '「彌」表持戒，「陀」表禪定。戒定相資，屬定善之列，可以漸增品位，故進九善慧地——成就微妙四無礙解，能徧十方善說法。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|陀陀': '兩輪都是「陀」——禪定。純定之擲力量最厚，屬定善之列，可以漸增品位，故進十法雲地——大法智雲含眾德水，蔭蔽一切，充滿法身。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|那佛': '「那」是見煩惱，「佛」表無漏善慧。這一擲雖帶見煩惱，無漏善慧仍可使品位漸增，故進九善慧地——成就微妙四無礙解，能徧十方善說法。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|謨佛': '「謨」是愛煩惱，「佛」表無漏善慧。這一擲雖帶愛煩惱，無漏善慧仍可使品位漸增，故進十法雲地——大法智雲含眾德水，蔭蔽一切，充滿法身。‖譜曰：（初歡喜地位下云：今約教門。故阿阿等散善不行。唯阿陀等三。名為定善。及那佛。謨佛。可以漸增品位。）',
  '八不動地|阿佛': '「阿」表布施，「佛」表無漏善慧。別教登地已證道同圓，此擲按其當位便同圓十住位——直斷一品無明而入初住，便能百界作佛、八相成道。‖譜曰：（初歡喜地位下云：若阿佛。則按位便同圓住。）',
  '八不動地|彌佛': '「彌」表持戒，「佛」表無漏善慧。此擲勝進，便成圓十行位——十住之後更斷十品無明。‖譜曰：（初歡喜地位下云：彌佛。陀佛。則勝進便成圓行圓向。）',
  '八不動地|陀佛': '「陀」表禪定，「佛」表無漏善慧。此擲勝進，便成圓十迴向位——十行之後更破十品無明。‖譜曰：（初歡喜地位下云：彌佛。陀佛。則勝進便成圓行圓向。）',
  '八不動地|佛佛': '兩輪都是「佛」，在此位表圓頓門。開麤顯妙，即為圓十地位——十迴向後更破一品無明。‖譜曰：（初歡喜地位下云：至於佛佛。則開麤顯妙。即為圓地也。下皆准知。）',
  '八不動地|那阿': '「那」是見煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '八不動地|謨阿': '「謨」是愛煩惱，「阿」表布施。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '八不動地|那彌': '「那」是見煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '八不動地|謨彌': '「謨」是愛煩惱，「彌」表持戒。惑善相為對治，二俱無力，所以不行，仍守本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '八不動地|那陀': '「那」是見煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',
  '八不動地|謨陀': '「謨」是愛煩惱，「陀」表禪定。惑善相為對治，二俱無力，所以不行，安住本位。‖譜曰：（見取位下云：其餘位中。以阿彌陀善。與那謨惡相為對治。二俱無力。所以並不行也。）',

